import re
def parse(v):
    if '+' in v: v=v.split('+',1)[0]
    if '-' in v: main,pre=v.split('-',1)
    else: main,pre=v,None
    parts=main.split('.')
    if len(parts)!=3: raise ValueError
    for p in parts:
        if not p.isdigit(): raise ValueError
        if len(p)>1 and p[0]=='0': raise ValueError
    major,minor,patch=map(int,parts)
    ids=[]
    if pre:
        for ident in pre.split('.'):
            if not re.fullmatch(r'[A-Za-z0-9-]+',ident): raise ValueError
            if ident.isdigit() and (len(ident)>1 and ident[0]=='0'): raise ValueError
            ids.append(ident)
    return (major,minor,patch,pre,ids)
def semver_compare(a,b):
    ta,tb=parse(a),parse(b)
    for x,y in zip(ta[:3],tb[:3]):
        if x!=y: return -1 if x<y else 1
    if ta[3] is None and tb[3] is not None: return 1
    if ta[3] is not None and tb[3] is None: return -1
    if ta[3] is None: return 0
    ia,ib=ta[4],tb[4]
    for i in range(min(len(ia),len(ib))):
        ai,bi=ia[i],ib[i]
        a_dig,b_dig=ai.isdigit(),bi.isdigit()
        if a_dig and b_dig:
            if int(ai)!=int(bi): return -1 if int(ai)<int(bi) else 1
        elif a_dig: return -1
        elif b_dig: return 1
        else:
            if ai!=bi: return -1 if ai<bi else 1
    if len(ia)<len(ib): return -1
    if len(ia)>len(ib): return 1
    return 0
